CREATE FUNCTION add_numbers(a INT, b INT) RETURNS INT AS 'SELECT a + b' LANGUAGE SQL;

CREATE OR REPLACE FUNCTION calc(x INT) RETURNS INT AS 'SELECT x * 2' LANGUAGE SQL;

CREATE FUNCTION order_count(uid INT) RETURNS INT AS $$
  SELECT COUNT(*) FROM orders WHERE user_id = uid;
$$ LANGUAGE SQL;

CREATE FUNCTION audit_orders() RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO audit_log (id, message) VALUES (1, 'order changed');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION audit_cols() RETURNS TRIGGER AS $$
BEGIN
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION process() RETURNS TRIGGER AS $$
BEGIN
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE FUNCTION refresh_stats() RETURNS TRIGGER AS $$
BEGIN
